package com.foldersforbanktags;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The folder list is the only thing this plugin stores, so it is the part worth
 * pinning down. None of these methods read or write config, so no client is
 * needed.
 */
public class FolderStoreTest
{
	private FolderStore store;

	@Before
	public void setUp()
	{
		store = new FolderStore(null, null);
	}

	private static List<String> tabs(String... names)
	{
		return Arrays.asList(names);
	}

	@Test
	public void tagBelongsToOneFolderOnly()
	{
		Folder herblore = store.create("Herblore", "potions");
		Folder combat = store.create("Combat", "melee");

		store.addTag(combat, "potions");

		assertEquals(combat, store.folderOf("potions"));
		assertFalse(herblore.getTags().contains("potions"));
	}

	@Test
	public void emptyingAFolderRemovesIt()
	{
		store.create("Herblore", "potions");
		assertEquals(1, store.folders().size());

		store.removeTag("potions");

		assertTrue(store.folders().isEmpty());
		assertNull(store.folderOf("potions"));
	}

	@Test
	public void deletingAFolderKeepsNothingBehind()
	{
		Folder folder = store.create("Herblore", "potions");
		store.addTag(folder, "herbs");

		store.delete(folder);

		assertTrue(store.folders().isEmpty());
		assertNull(store.folderOf("potions"));
		assertNull(store.folderOf("herbs"));
	}

	/**
	 * Core renames a tab as a single write with one name gone and one arrived. The
	 * folder has to follow it, or a rename quietly empties the folder.
	 */
	@Test
	public void renamedTabKeepsItsFolder()
	{
		Folder folder = store.create("Herblore", "potions");
		store.addTag(folder, "herbs");

		boolean changed = store.reconcile(tabs("potions", "herbs"), tabs("herbs", "brews"));

		assertTrue(changed);
		assertEquals(folder, store.folderOf("brews"));
		assertNull(store.folderOf("potions"));
		assertEquals(2, folder.getTags().size());
	}

	@Test
	public void deletedTabLeavesItsFolder()
	{
		Folder folder = store.create("Herblore", "potions");
		store.addTag(folder, "herbs");

		boolean changed = store.reconcile(tabs("potions", "herbs"), tabs("herbs"));

		assertTrue(changed);
		assertNull(store.folderOf("potions"));
		assertNotNull(store.folderOf("herbs"));
	}

	@Test
	public void deletingTheLastTabRemovesTheFolder()
	{
		store.create("Herblore", "potions");

		assertTrue(store.reconcile(tabs("potions"), Collections.emptyList()));
		assertTrue(store.folders().isEmpty());
	}

	@Test
	public void addingATabIsNotARename()
	{
		Folder folder = store.create("Herblore", "potions");

		boolean changed = store.reconcile(tabs("potions"), tabs("potions", "brews"));

		assertFalse(changed);
		assertEquals(folder, store.folderOf("potions"));
		assertNull(store.folderOf("brews"));
	}

	@Test
	public void reorderingIsNotAChange()
	{
		store.create("Herblore", "potions");

		assertFalse(store.reconcile(tabs("potions", "herbs"), tabs("herbs", "potions")));
		assertNotNull(store.folderOf("potions"));
	}

	@Test
	public void retainDropsMembersWhoseTabsAreGone()
	{
		Folder folder = store.create("Herblore", "potions");
		store.addTag(folder, "herbs");

		assertTrue(store.retain(tabs("herbs", "runes")));

		assertNull(store.folderOf("potions"));
		assertEquals(folder, store.folderOf("herbs"));
	}

	@Test
	public void retainLeavesAHealthyListAlone()
	{
		store.create("Herblore", "potions");

		assertFalse(store.retain(tabs("potions", "runes")));
		assertNotNull(store.folderOf("potions"));
	}

	@Test
	public void lookupIsCaseAndSpaceInsensitiveLikeBankTags()
	{
		Folder folder = store.create("Herblore", "Potions");

		assertEquals(folder, store.folderOf("potions"));
		assertEquals(folder, store.folderOf("POTIONS"));
	}

	@Test
	public void folderNamesAreCheckedCaseInsensitively()
	{
		store.create("Herblore", "potions");

		assertTrue(store.nameTaken("herblore"));
		assertFalse(store.nameTaken("Combat"));
	}
}

package com.foldersforbanktags;

import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The chooser used to stop at the eighth folder, so a ninth could exist and
 * never be picked. Paging has to reach every folder exactly once, whatever the
 * count.
 */
public class PagingTest
{
	@Test
	public void pageCountsAreRight()
	{
		assertEquals(1, FolderActions.pageCount(0));
		assertEquals(1, FolderActions.pageCount(1));
		assertEquals(1, FolderActions.pageCount(6));
		assertEquals(2, FolderActions.pageCount(7));
		assertEquals(2, FolderActions.pageCount(12));
		assertEquals(3, FolderActions.pageCount(13));
	}

	@Test
	public void everyFolderIsReachableExactlyOnce()
	{
		for (int count = 1; count <= 60; count++)
		{
			Set<Integer> seen = new HashSet<>();
			int total = 0;

			for (int page = 0; page < FolderActions.pageCount(count); page++)
			{
				int[] range = FolderActions.pageRange(count, page);
				assertTrue("page " + page + " of " + count + " runs backwards", range[0] <= range[1]);
				assertTrue("page " + page + " of " + count + " is too big", range[1] - range[0] <= 6);

				for (int i = range[0]; i < range[1]; i++)
				{
					seen.add(i);
					total++;
				}
			}

			assertEquals("every folder of " + count + " reachable", count, seen.size());
			assertEquals("no folder of " + count + " listed twice", count, total);
		}
	}

	@Test
	public void noPageIsEmptyWhenFoldersExist()
	{
		for (int count = 1; count <= 60; count++)
		{
			for (int page = 0; page < FolderActions.pageCount(count); page++)
			{
				int[] range = FolderActions.pageRange(count, page);
				assertTrue("empty page " + page + " of " + count, range[1] > range[0]);
			}
		}
	}

	@Test
	public void anOutOfRangePageIsClampedNotCrashed()
	{
		int[] range = FolderActions.pageRange(3, 99);
		assertEquals(0, range[0]);
		assertEquals(3, range[1]);
	}
}

package com.foldersforbanktags;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * Rows were all one height until a folder's tabs could be made smaller, and the
 * scroll limit was a row count divided out of the column height. Now it has to
 * be counted in pixels, so the sum of what is on screen still has to land in
 * the same place for tabs that are all the normal size.
 */
public class ScrollTest
{
	/** Core's tab, and the gap above it. */
	private static final int TAB = 40;
	private static final int GAP = 1;

	private static int[] rows(int count, int height)
	{
		int[] heights = new int[count];
		for (int i = 0; i < count; i++)
		{
			heights[i] = height;
		}
		return heights;
	}

	/** The column core sizes: room for a whole number of normal tabs. */
	private static int column(int tabs)
	{
		return tabs * (TAB + GAP);
	}

	@Test
	public void everythingFittingDoesNotScroll()
	{
		assertEquals(0, TabStrip.lastOffset(rows(5, TAB), column(8)));
	}

	@Test
	public void exactlyFillingDoesNotScroll()
	{
		assertEquals(0, TabStrip.lastOffset(rows(8, TAB), column(8)));
	}

	/**
	 * The old arithmetic, kept honest: normal tabs in a column that holds eight
	 * stop scrolling with the last eight showing.
	 */
	@Test
	public void normalTabsStopWhereTheRowCountUsedTo()
	{
		assertEquals(12 - 8, TabStrip.lastOffset(rows(12, TAB), column(8)));
	}

	/** Half-height tabs are half the cost, so more of them fit before scrolling. */
	@Test
	public void smallerTabsScrollLess()
	{
		int half = TAB / 2;
		int fits = column(8) / (half + GAP);
		assertEquals(20 - fits, TabStrip.lastOffset(rows(20, half), column(8)));
	}

	/**
	 * A heading at full height above its shrunken tabs, counted from the bottom up
	 * the way the clamp works. A column holding eight normal tabs is 328 pixels;
	 * fifteen half-height rows cost 315 and a sixteenth would cost 336, so the
	 * heading and the tab below it are the two that scroll off.
	 */
	@Test
	public void aMixOfHeightsIsCountedInPixels()
	{
		int[] heights = new int[17];
		heights[0] = TAB;
		for (int i = 1; i < heights.length; i++)
		{
			heights[i] = TAB / 2;
		}

		assertEquals(2, TabStrip.lastOffset(heights, column(8)));
	}

	@Test
	public void noRowsDoesNotScroll()
	{
		assertEquals(0, TabStrip.lastOffset(new int[0], column(8)));
	}
}

