package com.foldersforbanktags;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The underline is the only thing in the grid saying which tabs belong to which
 * folder, so it has to stop in the right places: at another folder, at a tab in
 * none, and at the end of a row. A line drawn one tile too far claims a tab is
 * in a folder it isn't.
 */
public class UnderlineTest
{
	private static final Object A = new Object();
	private static final Object B = new Object();

	/** Lays tiles out left to right, wrapping every {@code perRow}. */
	private static List<OverviewGrid.Placed> row(int perRow, Object... folders)
	{
		List<OverviewGrid.Placed> out = new ArrayList<>();
		for (int i = 0; i < folders.length; i++)
		{
			out.add(new OverviewGrid.Placed(folders[i], (i % perRow) * 48, (i / perRow) * 36));
		}
		return out;
	}

	private static List<int[]> runs(int perRow, Object... folders)
	{
		return OverviewGrid.runs(row(perRow, folders));
	}

	@Test
	public void tabsInNoFolderGetNoLine()
	{
		assertTrue(runs(8, null, null, null).isEmpty());
	}

	@Test
	public void aFolderAndItsTabsAreOneRun()
	{
		List<int[]> runs = runs(8, null, A, A, A, null);
		assertEquals(1, runs.size());
		assertArrayEquals(new int[]{1, 3}, runs.get(0));
	}

	/** A closed folder is a lone tile; underlining it would group it with nothing. */
	@Test
	public void aLoneFolderTileGetsNoLine()
	{
		assertTrue(runs(8, null, A, null).isEmpty());
	}

	@Test
	public void twoFoldersSideBySideStayApart()
	{
		List<int[]> runs = runs(8, A, A, B, B);
		assertEquals(2, runs.size());
		assertArrayEquals(new int[]{0, 1}, runs.get(0));
		assertArrayEquals(new int[]{2, 3}, runs.get(1));
	}

	@Test
	public void aFolderWrappingOntoTheNextRowIsTwoLines()
	{
		// Four per row: A takes the last two of row one and the first two of row two.
		List<int[]> runs = runs(4, null, null, A, A, A, A, null, null);
		assertEquals(2, runs.size());
		assertArrayEquals(new int[]{2, 3}, runs.get(0));
		assertArrayEquals(new int[]{4, 5}, runs.get(1));
	}

	@Test
	public void aFolderEndingExactlyAtTheRowEdgeIsOneLine()
	{
		List<int[]> runs = runs(4, null, null, A, A);
		assertEquals(1, runs.size());
		assertArrayEquals(new int[]{2, 3}, runs.get(0));
	}

	/**
	 * A wrap that leaves the folder's header alone at the end of a row still marks
	 * it, or the tabs below look like they belong to nothing.
	 */
	@Test
	public void aWrapLeavingOneTileBehindStillMarksIt()
	{
		List<int[]> runs = runs(4, null, null, null, A, A, A);
		assertEquals(2, runs.size());
		assertArrayEquals(new int[]{3, 3}, runs.get(0));
		assertArrayEquals(new int[]{4, 5}, runs.get(1));
	}

	/**
	 * The reported case: the folder fills the end of one row and its last tab lands
	 * alone on the next. That tab is in the folder and has to say so.
	 */
	@Test
	public void aWrapLeavingOneTabOnTheNextRowStillMarksIt()
	{
		List<int[]> runs = runs(4, null, A, A, A, A);
		assertEquals(2, runs.size());
		assertArrayEquals(new int[]{1, 3}, runs.get(0));
		assertArrayEquals(new int[]{4, 4}, runs.get(1));
	}

	@Test
	public void runsNeverOverlapOrRunBackwards()
	{
		List<int[]> runs = runs(4, A, A, B, B, B, null, A, A);
		int previousEnd = -1;
		for (int[] run : runs)
		{
			assertTrue(Arrays.toString(run), run[0] > previousEnd);
			assertTrue(Arrays.toString(run), run[1] >= run[0]);
			previousEnd = run[1];
		}
	}
}

package com.foldersforbanktags;

import java.util.Arrays;
import java.util.List;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The grouped order is written back into the Bank Tags tab list, so it has to
 * be a permutation of what went in: same tabs, same count, none invented and
 * none dropped. Most of the tests below check that from one angle or another,
 * plus that the rows drawn match the order stored.
 */
public class RowsTest
{
	private FolderStore store;

	@Before
	public void setUp()
	{
		store = new FolderStore(null, null);
	}

	private static List<String> tabs(String... names)
	{
		return Arrays.asList(names);
	}

	private List<String> rowTags(List<String> order)
	{
		List<String> out = new java.util.ArrayList<>();
		for (Rows.Row row : Rows.build(store, order))
		{
			out.add(row.isHeader() ? "[" + row.folder().getName() + "]" : row.tag());
		}
		return out;
	}

	@Test
	public void withoutFoldersNothingMoves()
	{
		assertEquals(tabs("a", "b", "c"), Rows.grouped(store, tabs("a", "b", "c")));
	}

	@Test
	public void scatteredMembersGatherAtTheFirstOne()
	{
		Folder folder = store.create("Skilling", "herbs");
		store.addTag(folder, "runes");

		assertEquals(tabs("a", "herbs", "runes", "b"), Rows.grouped(store, tabs("a", "herbs", "b", "runes")));
	}

	@Test
	public void theFolderTakesTheFirstMembersPlace()
	{
		Folder folder = store.create("Skilling", "runes");
		store.addTag(folder, "herbs");

		// "herbs" comes first in the tab list, so that is where the folder sits.
		assertEquals(tabs("herbs", "runes", "a"), Rows.grouped(store, tabs("herbs", "a", "runes")));
	}

	@Test
	public void twoFoldersKeepTheirOwnPlaces()
	{
		Folder skilling = store.create("Skilling", "herbs");
		store.addTag(skilling, "runes");
		Folder combat = store.create("Combat", "melee");
		store.addTag(combat, "range");

		assertEquals(
			tabs("herbs", "runes", "melee", "range", "misc"),
			Rows.grouped(store, tabs("herbs", "melee", "runes", "misc", "range")));
	}

	/** Nothing is ever gained or lost by grouping. */
	@Test
	public void groupingIsAlwaysAPermutation()
	{
		Folder skilling = store.create("Skilling", "herbs");
		store.addTag(skilling, "runes");
		store.addTag(skilling, "logs");
		Folder combat = store.create("Combat", "melee");

		List<String> before = tabs("a", "melee", "herbs", "b", "runes", "c", "logs");
		List<String> after = Rows.grouped(store, before);

		assertEquals(before.size(), after.size());
		assertTrue(after.containsAll(before));
		assertTrue(before.containsAll(after));
		assertEquals(after.size(), new java.util.HashSet<>(after).size());
	}

	@Test
	public void groupingAnAlreadyGroupedListChangesNothing()
	{
		Folder folder = store.create("Skilling", "herbs");
		store.addTag(folder, "runes");

		List<String> once = Rows.grouped(store, tabs("a", "herbs", "b", "runes"));
		assertEquals(once, Rows.grouped(store, once));
	}

	@Test
	public void anOpenFolderShowsItsTabs()
	{
		Folder folder = store.create("Skilling", "herbs");
		store.addTag(folder, "runes");

		List<String> order = Rows.grouped(store, tabs("a", "herbs", "runes"));
		assertEquals(tabs("a", "[Skilling]", "herbs", "runes"), rowTags(order));
	}

	@Test
	public void aShutFolderHidesThemButKeepsThemStored()
	{
		Folder folder = store.create("Skilling", "herbs");
		store.addTag(folder, "runes");
		folder.setCollapsed(true);

		List<String> order = Rows.grouped(store, tabs("a", "herbs", "runes"));

		// Drawn: heading only. Stored: still grouped, so turning the plugin off
		// leaves them side by side.
		assertEquals(tabs("a", "[Skilling]"), rowTags(order));
		assertEquals(tabs("a", "herbs", "runes"), order);
	}

	@Test
	public void aTabTakenOutOfAFolderMovesPastIt()
	{
		Folder folder = store.create("Skilling", "herbs");
		store.addTag(folder, "runes");
		store.addTag(folder, "logs");

		List<String> grouped = Rows.grouped(store, tabs("herbs", "runes", "logs"));
		store.removeTag("runes");

		assertEquals(tabs("herbs", "logs", "runes"), Rows.grouped(store, grouped));
	}
}

package com.foldersforbanktags;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Core rebuilds the tag column from its own handlers without firing a script,
 * so noticing that our rows have gone is the only way they come back. The case
 * that got missed was importing a tag tab: core truncates the container's
 * children, and by the time we look, scan() has already forgotten our widgets,
 * so there is nothing left for the identity check to compare.
 */
public class HealTest
{
	private static final boolean INTACT = true;
	private static final boolean GONE = false;

	@Test
	public void nothingChangedIsNotStale()
	{
		assertFalse(TabStrip.stale(20, 20, INTACT, true, true));
	}

	@Test
	public void childCountChangingIsStale()
	{
		assertTrue(TabStrip.stale(22, 20, INTACT, true, true));
	}

	@Test
	public void ourRowsBeingDetachedIsStale()
	{
		assertTrue(TabStrip.stale(20, 20, GONE, true, true));
	}

	/**
	 * Importing a tag tab. Core replaced two of our widgets with two of its own,
	 * so the count matches; scan() forgot ours, so the identity check has
	 * nothing to compare and reports intact. Only the third signal is left.
	 */
	@Test
	public void havingHadRowsButHoldingNoneIsStale()
	{
		assertTrue(TabStrip.stale(20, 20, INTACT, true, false));
	}

	/** With no folders to draw there is nothing to miss, so no redraw loop. */
	@Test
	public void neverHavingHadRowsIsNotStale()
	{
		assertFalse(TabStrip.stale(20, 20, INTACT, false, false));
	}
}

package com.foldersforbanktags;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * The folder list, and the tag to folder index built from it.
 *
 * The only thing this plugin owns. It lives in its own config group and nothing
 * is ever written into {@code banktags}, so the tag list stays the one source
 * of truth for which tabs exist: turn this plugin off and the flat column comes
 * back untouched.
 */
@Slf4j
@Singleton
class FolderStore
{
	static final String GROUP = "foldersforbanktags";
	static final String KEY_FOLDERS = "folders";

	/**
	 * Bumped when the stored shape changes. Anything else reads as no folders
	 * rather than being guessed at, including the unversioned data version 1 of
	 * this plugin wrote.
	 */
	private static final int FORMAT = 2;

	private static class Stored
	{
		@SerializedName("version")
		int version;

		@SerializedName("folders")
		List<Folder> folders;
	}

	private final ConfigManager configManager;
	private final Gson gson;

	private final List<Folder> folders = new ArrayList<>();
	private final Map<String, Folder> byTag = new HashMap<>();

	@Inject
	FolderStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	void load()
	{
		folders.clear();

		String json = configManager.getConfiguration(GROUP, KEY_FOLDERS);
		if (json != null && !json.isEmpty())
		{
			try
			{
				Stored stored = gson.fromJson(json, Stored.class);
				if (stored != null && stored.version == FORMAT && stored.folders != null)
				{
					for (Folder folder : stored.folders)
					{
						if (folder != null && folder.getId() != null && folder.getName() != null)
						{
							if (folder.getTags() == null)
							{
								folder.setTags(new ArrayList<>());
							}
							folders.add(folder);
						}
					}
				}
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Could not read stored folders; starting with none", e);
			}
		}

		reindex();
	}

	void save()
	{
		Stored stored = new Stored();
		stored.version = FORMAT;
		stored.folders = folders;

		configManager.setConfiguration(GROUP, KEY_FOLDERS, gson.toJson(stored));
	}

	private void reindex()
	{
		byTag.clear();
		for (Folder folder : folders)
		{
			// Over a copy, since a tag claimed by two folders is dropped from
			// the second rather than left to disagree with the index.
			for (String tag : new ArrayList<>(folder.getTags()))
			{
				String key = Text.standardize(tag);
				if (key.isEmpty() || byTag.containsKey(key))
				{
					folder.getTags().remove(tag);
					continue;
				}
				byTag.put(key, folder);
			}
		}
	}

	List<Folder> folders()
	{
		return folders;
	}

	boolean isEmpty()
	{
		return folders.isEmpty();
	}

	@Nullable
	Folder folderOf(String tag)
	{
		return byTag.get(Text.standardize(tag));
	}

	@Nullable
	Folder byId(String id)
	{
		for (Folder folder : folders)
		{
			if (folder.getId().equals(id))
			{
				return folder;
			}
		}
		return null;
	}

	boolean nameTaken(String name)
	{
		for (Folder folder : folders)
		{
			if (folder.getName().equalsIgnoreCase(name))
			{
				return true;
			}
		}
		return false;
	}

	Folder create(String name, String firstTag)
	{
		Folder folder = new Folder();
		folder.setId(UUID.randomUUID().toString());
		folder.setName(name);
		folders.add(folder);
		addTag(folder, firstTag);
		return folder;
	}

	void addTag(Folder folder, String tag)
	{
		String key = Text.standardize(tag);
		if (key.isEmpty())
		{
			return;
		}

		removeTag(key);
		folder.getTags().add(key);
		byTag.put(key, folder);
	}

	/**
	 * Open or close every folder.
	 *
	 * @return whether anything changed, so the caller knows whether to save
	 */
	boolean setAllCollapsed(boolean collapsed)
	{
		boolean changed = false;
		for (Folder folder : folders)
		{
			if (folder.isCollapsed() != collapsed)
			{
				folder.setCollapsed(collapsed);
				changed = true;
			}
		}
		return changed;
	}

	/** Takes a tag out of whatever folder holds it, deleting one left empty. */
	void removeTag(String tag)
	{
		String key = Text.standardize(tag);
		Folder folder = byTag.remove(key);
		if (folder == null)
		{
			return;
		}

		folder.getTags().remove(key);
		if (folder.getTags().isEmpty())
		{
			folders.remove(folder);
		}
	}

	/** Deletes the folder. The tabs inside are left where they are. */
	void delete(Folder folder)
	{
		for (String tag : folder.getTags())
		{
			byTag.remove(tag);
		}
		folders.remove(folder);
	}

	/**
	 * Forget tags that no longer exist, and follow one that was renamed. Bank Tags
	 * renames a tab by removing the old name and adding the new one in a single
	 * write, so exactly one gone and one arrived is a rename and the folder
	 * follows it. Anything else is a deletion.
	 *
	 * @return whether anything changed, so the caller knows whether to save
	 */
	boolean reconcile(List<String> before, List<String> after)
	{
		Set<String> gone = new HashSet<>(before);
		gone.removeAll(after);

		Set<String> arrived = new HashSet<>(after);
		arrived.removeAll(before);

		if (gone.isEmpty())
		{
			return false;
		}

		boolean changed = false;

		if (gone.size() == 1 && arrived.size() == 1)
		{
			String from = gone.iterator().next();
			String to = arrived.iterator().next();
			Folder folder = byTag.get(from);
			if (folder != null)
			{
				int at = folder.getTags().indexOf(from);
				folder.getTags().set(at, to);
				byTag.remove(from);
				byTag.put(to, folder);
				changed = true;
			}
			return changed;
		}

		for (String tag : gone)
		{
			if (byTag.containsKey(tag))
			{
				removeTag(tag);
				changed = true;
			}
		}

		return changed;
	}

	/**
	 * Drop members that are not in the given tab list. Catches tabs that disappear
	 * without a config event to pair up, such as another plugin editing the list
	 * or a config sync from another client. Only removes folder membership; the
	 * tag itself is not ours to touch.
	 */
	boolean retain(Collection<String> live)
	{
		Set<String> keep = new HashSet<>();
		for (String tag : live)
		{
			keep.add(Text.standardize(tag));
		}

		boolean changed = false;
		for (String tag : new ArrayList<>(byTag.keySet()))
		{
			if (!keep.contains(tag))
			{
				removeTag(tag);
				changed = true;
			}
		}
		return changed;
	}
}

package com.foldersforbanktags;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.SoundEffectID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.game.chatbox.ChatboxTextMenuInput;
import net.runelite.client.util.Text;

/**
 * Everything a folder can be asked to do, and the prompts that ask.
 *
 * Kept apart from the drawing, so the column stays a function of the tab list
 * and the folder list. Nothing here touches a widget; it changes the folder
 * list and asks for a redraw.
 */
@Slf4j
@Singleton
class FolderActions
{
	/** Characters that would break a widget name or a colour tag. */
	private static final String REJECTED = "</>:";

	/** Folders per page, leaving room for the paging and cancel lines. */
	private static final int PAGE_SIZE = 6;

	private final Client client;
	private final ClientThread clientThread;
	private final FolderStore store;
	private final TabStrip strip;
	private final OverviewGrid overview;
	private final BankSearch bankSearch;
	private final TabOrder order;
	private final ChatboxPanelManager chatboxPanelManager;
	private final ChatboxItemSearch itemSearch;
	private final ChatMessageManager chatMessageManager;

	@Inject
	FolderActions(
		Client client,
		ClientThread clientThread,
		FolderStore store,
		TabStrip strip,
		OverviewGrid overview,
		BankSearch bankSearch,
		TabOrder order,
		ChatboxPanelManager chatboxPanelManager,
		ChatboxItemSearch itemSearch,
		ChatMessageManager chatMessageManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.store = store;
		this.strip = strip;
		this.overview = overview;
		this.bankSearch = bankSearch;
		this.order = order;
		this.chatboxPanelManager = chatboxPanelManager;
		this.itemSearch = itemSearch;
		this.chatMessageManager = chatMessageManager;
	}

	// ------------------------------------------------------------------
	// Options on a folder row
	// ------------------------------------------------------------------

	void onFolderOp(int op, String folderId)
	{
		Folder folder = store.byId(folderId);
		if (folder == null)
		{
			return;
		}

		switch (op)
		{
			case TabStrip.OP_TOGGLE:
				folder.setCollapsed(!folder.isCollapsed());
				store.save();
				client.playSoundEffect(SoundEffectID.UI_BOOP);
				apply();
				break;

			case TabStrip.OP_RENAME:
				rename(folder);
				break;

			case TabStrip.OP_ICON:
				changeIcon(folder);
				break;

			case TabStrip.OP_DELETE:
				confirmDelete(folder);
				break;

			default:
				break;
		}
	}

	private void rename(Folder folder)
	{
		chatboxPanelManager.openTextInput("Enter new name for folder \"" + folder.getName() + "\":")
			.addCharValidator(c -> REJECTED.indexOf(c) == -1)
			.onDone((String name) -> clientThread.invoke(() ->
			{
				String cleaned = clean(name);
				if (cleaned == null || cleaned.equalsIgnoreCase(folder.getName()))
				{
					return;
				}

				String problem = reject(cleaned);
				if (problem != null)
				{
					say(problem);
					return;
				}

				folder.setName(cleaned);
				store.save();
				apply();
			}))
			.build();
	}

	private void changeIcon(Folder folder)
	{
		itemSearch
			.tooltipText("Folder icon (" + folder.getName() + ")")
			.onItemSelected((Integer itemId) -> clientThread.invokeLater(() ->
			{
				folder.setIcon(itemId);
				store.save();
				apply();
			}))
			.build();
	}

	private void confirmDelete(Folder folder)
	{
		chatboxPanelManager.openTextMenuInput("Delete folder \"" + folder.getName() + "\"?")
			.option("1. Delete it. The tabs inside are kept.", () -> clientThread.invoke(() ->
			{
				store.delete(folder);
				store.save();
				apply();
			}))
			.option("2. Cancel", () ->
			{
			})
			.build();
	}

	// ------------------------------------------------------------------
	// Options on a tag tab
	// ------------------------------------------------------------------

	/**
	 * Ask where a tab should go.
	 *
	 * Split in two because listing every folder alongside "new folder" and
	 * "cancel" put eight lines in the chatbox and quietly stopped at the eighth
	 * folder, so past that a folder existed but couldn't be picked. The short
	 * question keeps the common case to three lines, and the list that follows is
	 * paged, so every folder is reachable however many there are.
	 */
	void chooseFolder(String tag)
	{
		if (store.folders().isEmpty())
		{
			// Nothing to choose between yet, so skip straight to naming one.
			newFolder(tag);
			return;
		}

		chatboxPanelManager.openTextMenuInput("Add \"" + tag + "\" to")
			.option("1. An existing folder", () -> clientThread.invoke(() -> chooseExisting(tag, 0)))
			.option("2. A new folder", () -> clientThread.invoke(() -> newFolder(tag)))
			.option("3. Cancel", () ->
			{
			})
			.build();
	}

	/** How many pages a given number of folders needs. Never fewer than one. */
	static int pageCount(int folders)
	{
		return Math.max(1, (folders + PAGE_SIZE - 1) / PAGE_SIZE);
	}

	/** The folders shown on a page, as an index range into the folder list. */
	static int[] pageRange(int folders, int page)
	{
		int current = Math.max(0, Math.min(page, pageCount(folders) - 1));
		int from = current * PAGE_SIZE;
		return new int[]{Math.min(from, folders), Math.min(folders, from + PAGE_SIZE)};
	}

	/**
	 * One page of folders. Paging wraps rather than offering both a next and a
	 * previous, which would cost another line and undo the point of paging. The
	 * page number goes in the title so it is clear where the list has got to.
	 */
	private void chooseExisting(String tag, int page)
	{
		List<Folder> folders = store.folders();
		if (folders.isEmpty())
		{
			// Every folder went away while the chatbox was open; taking the
			// last tab out of one from elsewhere deletes it.
			newFolder(tag);
			return;
		}

		int pages = pageCount(folders.size());
		int current = Math.max(0, Math.min(page, pages - 1));
		int[] range = pageRange(folders.size(), current);
		int from = range[0];
		int to = range[1];

		ChatboxTextMenuInput menu = chatboxPanelManager.openTextMenuInput(
			pages > 1
				? "Add \"" + tag + "\" to (" + (current + 1) + " of " + pages + ")"
				: "Add \"" + tag + "\" to");

		int line = 1;
		for (int i = from; i < to; i++)
		{
			// By id, not by object: the chatbox answers later, and by then the
			// folder may be gone.
			String id = folders.get(i).getId();
			menu.option(line++ + ". " + folders.get(i).getName(), () -> clientThread.invoke(() ->
			{
				Folder folder = store.byId(id);
				if (folder != null)
				{
					fileInto(folder, tag);
				}
			}));
		}

		if (pages > 1)
		{
			int next = (current + 1) % pages;
			menu.option(line++ + ". More folders...", () -> clientThread.invoke(() -> chooseExisting(tag, next)));
		}

		menu.option(line + ". Cancel", () ->
		{
		});
		menu.build();
	}

	void newFolder(String tag)
	{
		chatboxPanelManager.openTextInput("Name for the new folder:")
			.addCharValidator(c -> REJECTED.indexOf(c) == -1)
			.onDone((String name) -> clientThread.invoke(() ->
			{
				String cleaned = clean(name);
				if (cleaned == null)
				{
					return;
				}

				String problem = reject(cleaned);
				if (problem != null)
				{
					say(problem);
					return;
				}

				store.create(cleaned, tag);
				store.save();
				apply();
			}))
			.build();
	}

	/**
	 * Put a tab in a folder. It is also moved next to the folder's other members
	 * in the Bank Tags order, so what is drawn and what is stored agree: turn this
	 * plugin off and the grouped tabs are still next to each other.
	 */
	void fileInto(Folder folder, String tag)
	{
		String key = Text.standardize(tag);
		if (store.folderOf(key) == folder)
		{
			return;
		}

		// The chatbox answers on its own schedule, by which time the tab may have
		// been deleted, leaving the folder pointing at nothing.
		if (!order.isTab(key))
		{
			return;
		}

		List<String> flat = strip.tags();
		List<String> members = membersInOrder(folder, flat);

		store.addTag(folder, key);
		if (folder.isCollapsed())
		{
			// Open it, or the tab looks like it vanished.
			folder.setCollapsed(false);
		}
		store.save();

		if (!members.isEmpty())
		{
			order.move(singleton(key), members.get(members.size() - 1), true, flat);
		}

		apply();
	}

	void removeFrom(String tag)
	{
		store.removeTag(tag);
		store.save();
		apply();
	}

	// ------------------------------------------------------------------
	// Dragging
	// ------------------------------------------------------------------

	/** Move a whole folder to sit where a tab currently is. */
	void moveFolderToTag(String folderId, String anchorTag)
	{
		Folder folder = store.byId(folderId);
		if (folder == null)
		{
			return;
		}

		List<String> flat = strip.tags();
		List<String> members = membersInOrder(folder, flat);
		if (members.isEmpty() || members.contains(Text.standardize(anchorTag)))
		{
			return;
		}

		int from = flat.indexOf(members.get(0));
		int to = flat.indexOf(Text.standardize(anchorTag));
		if (from < 0 || to < 0)
		{
			return;
		}

		if (order.move(members, anchorTag, to > from, flat))
		{
			apply();
		}
	}

	/** Move a whole folder to sit where another folder currently is. */
	void moveFolderToFolder(String folderId, String targetId)
	{
		if (folderId.equals(targetId))
		{
			return;
		}

		Folder folder = store.byId(folderId);
		Folder target = store.byId(targetId);
		if (folder == null || target == null)
		{
			return;
		}

		List<String> flat = strip.tags();
		List<String> members = membersInOrder(folder, flat);
		List<String> targetMembers = membersInOrder(target, flat);
		if (members.isEmpty() || targetMembers.isEmpty())
		{
			return;
		}

		int from = flat.indexOf(members.get(0));
		int to = flat.indexOf(targetMembers.get(0));
		if (from < 0 || to < 0)
		{
			return;
		}

		boolean after = to > from;
		String anchor = after ? targetMembers.get(targetMembers.size() - 1) : targetMembers.get(0);

		if (order.move(members, anchor, after, flat))
		{
			apply();
		}
	}

	/**
	 * Show the change. The column repacks itself and needs nothing more, but the
	 * overview has no real items in it, so how far the bank scrolls depends on how
	 * many rows the grid has, and opening or closing a folder changes that. Asking
	 * core to rebuild reruns the script that sets the scroll height.
	 */
	private void apply()
	{
		if (overview.isActive())
		{
			bankSearch.layoutBank();
		}
		else
		{
			strip.refresh();
		}
	}

	private List<String> membersInOrder(Folder folder, List<String> flat)
	{
		List<String> out = new ArrayList<>();
		for (String tag : flat)
		{
			if (store.folderOf(tag) == folder)
			{
				out.add(tag);
			}
		}
		return out;
	}

	private static List<String> singleton(String tag)
	{
		List<String> out = new ArrayList<>(1);
		out.add(tag);
		return out;
	}

	@Nullable
	private static String clean(@Nullable String name)
	{
		if (name == null)
		{
			return null;
		}
		String trimmed = name.trim();
		return trimmed.isEmpty() ? null : trimmed;
	}

	/**
	 * Why a name can't be used, or null if it can. A folder must not be named
	 * after an existing tag: Bank Tags matches a dropped widget to a tab by the
	 * name written on it, so a folder wearing a tag's name would be a second
	 * answer to a question core expects to have one.
	 */
	@Nullable
	private String reject(String name)
	{
		if (store.nameTaken(name))
		{
			return "There is already a folder called \"" + name + "\".";
		}

		String key = Text.standardize(name);
		for (String tag : strip.tags())
		{
			if (tag.equals(key))
			{
				return "\"" + name + "\" is the name of a tag tab. Folders need a name of their own.";
			}
		}

		return null;
	}

	void say(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}
}

package com.foldersforbanktags;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetDrag;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsConfig;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * Collapsible folders for the bank tag tab column.
 *
 * An add-on rather than a replacement: Bank Tags draws its column as it always
 * does and this runs afterwards on the same event to rearrange it. Every tab is
 * still core's widget, so rename, delete, export, layouts, icons and dropping
 * an item onto a tab all keep working. No tag data is stored here.
 *
 * The subscriber priorities are at the extremes on purpose: negative where core
 * has to have finished first, positive where a drop has to be taken off core
 * before it reads one of our rows as a tab.
 */
@Slf4j
@PluginDescriptor(
	name = "Folders for Bank Tags",
	description = "Group bank tag tabs into collapsible folders",
	tags = {"bank", "tag", "tags", "tab", "tabs", "folder", "folders", "organise", "organize"}
)
@PluginDependency(BankTagsPlugin.class)
public class FoldersForBankTagsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private FolderStore store;

	@Inject
	private TabStrip strip;

	@Inject
	private OverviewGrid overview;

	@Inject
	private FolderActions actions;

	@Inject
	private TabOrder tabOrder;

	@Inject
	private FoldersForBankTagsConfig config;

	@Inject
	private BankTagsConfig bankTagsConfig;

	@Inject
	private EventBus eventBus;


	/** Only warn about the column being switched off once. */
	private boolean warned;

	/** Height the overview grid needs, or -1 when it is not open. */
	private int overviewHeight = -1;

	/** A drop core is about to rebuild its tabs for. See {@link DropRepair}. */
	private boolean dropped;

	private final DropRepair dropRepair = new DropRepair(this::repairAfterDrop);

	@Provides
	FoldersForBankTagsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FoldersForBankTagsConfig.class);
	}

	@Override
	protected void startUp()
	{
		eventBus.register(dropRepair);

		clientThread.invoke(() ->
		{
			warned = false;
			store.load();
			strip.onBankOpened();
			// The bank may already be open when the plugin is switched on.
			redraw();
		});
	}

	@Override
	protected void shutDown()
	{
		eventBus.unregister(dropRepair);
		clientThread.invoke(strip::detach);
	}

	// ------------------------------------------------------------------
	// Bank lifecycle
	// ------------------------------------------------------------------

	/**
	 * Runs last on this event. Core builds and stacks its tabs here, and both the
	 * core layout manager and Bank Tag Layouts lay the bank out around the same
	 * script, so waiting for all of them keeps us out of their way. It is also why
	 * there is only ever one set of tab widgets: we move core's rather than
	 * building our own.
	 */
	@Subscribe(priority = -100)
	public void onScriptPreFired(ScriptPreFired event)
	{
		int id = event.getScriptId();

		if (id == ScriptID.BANKMAIN_INIT)
		{
			strip.onBankOpened();
			nudgeIfColumnOff();
			if (config.collapseOnOpen())
			{
				collapseAll();
			}
			return;
		}

		if (id == ScriptID.BANKMAIN_FINISHBUILDING)
		{
			redrawAndResize();
		}
		else if (id == ScriptID.BANKMAIN_SIZE_CHECK)
		{
			onSizeCheck();
		}
	}

	/**
	 * Draw both views. The column hands back the order it drew in, so the grid
	 * lays out the same way without working it out again.
	 */
	private void redraw()
	{
		overviewHeight = overview.refresh(strip.refresh());
	}

	/**
	 * Draw both views and fix up the bank's scroll height. Only safe from inside
	 * [proc,bankmain_finishbuilding], since it writes to that script's arguments
	 * while they are still on the stack.
	 *
	 * The overview has no real items in it, so the height is whatever the grid
	 * says. Core writes it a moment before we do, but our grid has folder tiles in
	 * it and hides the tabs inside closed folders, so the row count differs.
	 */
	private void redrawAndResize()
	{
		redraw();

		if (overviewHeight < 0)
		{
			return;
		}

		int[] stack = client.getIntStack();
		int size = client.getIntStackSize();
		if (size >= 9)
		{
			stack[size - 9] = overviewHeight;
		}
	}

	/**
	 * Detect a bank resize the way core does: the script is about to resize the
	 * container, so compare the new size against the current one and defer the
	 * redraw until it has been applied. Core defers the same way, and ours is
	 * queued after it.
	 */
	private void onSizeCheck()
	{
		int[] stack = client.getIntStack();
		int size = client.getIntStackSize();
		if (size < 5)
		{
			return;
		}

		Widget widget = client.getWidget(stack[size - 5]);
		if (widget == null)
		{
			return;
		}

		if (widget.getWidth() != stack[size - 4] || widget.getHeight() != stack[size - 3])
		{
			clientThread.invokeLater(strip::refresh);
		}
	}

	// The storage popup covers part of the column, so core repacks its rows into
	// the height that is left and we repack ours into the same space.
	@Subscribe(priority = -100)
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_POPUP_TAB_DRAW)
		{
			strip.refresh();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			strip.onBankClosed();
			overview.onBankClosed();
		}
	}

	/**
	 * Warn once, and only if there are folders to lose, that the column this
	 * plugin decorates is switched off. We don't turn the setting back on
	 * ourselves, since it belongs to another plugin.
	 */
	private void nudgeIfColumnOff()
	{
		if (bankTagsConfig.tabs() || store.isEmpty())
		{
			warned = false;
			return;
		}

		if (!warned)
		{
			warned = true;
			actions.say("Folders for Bank Tags is idle: turn \"Tag tabs\" back on in the Bank Tags plugin "
				+ "and your folders will come back with the column.");
		}
	}

	private void collapseAll()
	{
		if (store.setAllCollapsed(true))
		{
			store.save();
		}
	}

	// ------------------------------------------------------------------
	// Keeping up with core
	// ------------------------------------------------------------------

	/**
	 * Core rebuilds its tabs from inside its own option handlers (delete, rename,
	 * dropping one tab on another) and each rebuild replaces the container's
	 * children, taking our folder rows with it. None of that raises an event, so
	 * instead of chasing every call site, notice the rows have gone and put them
	 * back. Two array reads when there is nothing to do.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		strip.heal();

		if (overview.isStale())
		{
			redraw();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BankTagsPlugin.CONFIG_GROUP.equals(event.getGroup()))
		{
			// Our own regrouping write comes back through here. Reconciling it
			// would diff a change we made and redraw a column we just drew.
			if (BankTagsPlugin.TAG_TABS_CONFIG.equals(event.getKey()) && !tabOrder.isWriting())
			{
				onTabListChanged(csv(event.getOldValue()), csv(event.getNewValue()));
			}
			else if ("useTabs".equals(event.getKey()))
			{
				warned = false;
				clientThread.invokeLater(this::redraw);
			}
			return;
		}

		// Settings only. Reacting to our own folder write would schedule a redraw,
		// which can save, which writes again, and the scroll position is written by
		// the redraw that already drew it.
		if (FolderStore.GROUP.equals(event.getGroup())
			&& !FolderStore.KEY_FOLDERS.equals(event.getKey())
			&& !FoldersForBankTagsConfig.KEY_SCROLL.equals(event.getKey()))
		{
			clientThread.invokeLater(this::redraw);
		}
	}

	/**
	 * Follow a tab core renamed, and let go of one it deleted. Core renames by
	 * removing the old name and adding the new one in a single write, so exactly
	 * one name gone and one arrived is a rename; anything else is a deletion. Both
	 * lists come off the config event, so there is no cached copy to go stale.
	 */
	private void onTabListChanged(List<String> before, List<String> after)
	{
		clientThread.invokeLater(() ->
		{
			if (store.reconcile(before, after))
			{
				store.save();
			}
			redraw();
		});
	}

	private static List<String> csv(@Nullable String value)
	{
		if (value == null || value.isEmpty())
		{
			return new ArrayList<>();
		}
		return new ArrayList<>(Text.fromCSV(value));
	}

	// ------------------------------------------------------------------
	// Menu
	// ------------------------------------------------------------------

	/**
	 * Add the folder options to a tab's right-click menu. Done here rather than as
	 * widget options, because adding one would mean replacing the listener that
	 * answers all of core's.
	 *
	 * {@code MenuOpened} fires once, after every entry has been collected, unlike
	 * {@code MenuEntryAdded}, which would add ours once for each of the six
	 * options core puts on a tab.
	 */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		String tag = null;
		for (MenuEntry entry : event.getMenuEntries())
		{
			tag = tagAt(widgetFor(entry));
			if (tag != null)
			{
				break;
			}
		}

		if (tag == null)
		{
			return;
		}

		final String subject = tag;
		String target = ColorUtil.wrapWithColorTag(tag, JagexColors.MENU_TARGET);

		if (store.folderOf(tag) != null)
		{
			client.getMenu().createMenuEntry(-1)
				.setOption("Remove from folder")
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> actions.removeFrom(subject));
		}
		else
		{
			client.getMenu().createMenuEntry(-1)
				.setOption("Add to folder")
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> actions.chooseFolder(subject));
		}
	}

	@Nullable
	private Widget widgetFor(MenuEntry entry)
	{
		Widget widget = entry.getWidget();
		if (widget != null)
		{
			return widget;
		}

		if (entry.getParam1() != InterfaceID.Bankmain.ITEMS_CONTAINER || entry.getParam0() < 0)
		{
			return null;
		}

		Widget parent = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		return parent == null ? null : parent.getChild(entry.getParam0());
	}

	// ------------------------------------------------------------------
	// Dragging
	// ------------------------------------------------------------------

	/**
	 * Runs before core, and only for drops involving one of our rows. A folder row
	 * is a named child of the same container as a tab, so core would read a bank
	 * item dropped on one as "tag this item with the folder's name" and create a
	 * tag nobody asked for. Nulling the drop target is how core cancels a drop
	 * itself for its "prevent tag tab drags" option.
	 *
	 * Every other drop is left alone, so reordering tabs and tagging an item by
	 * dropping it on a tab work exactly as they do without this plugin.
	 */
	@Subscribe(priority = 100)
	public void onWidgetDrag(WidgetDrag event)
	{
		Widget dragged = client.getDraggedWidget();
		Widget target = client.getDraggedOnWidget();

		if (dragged == null || target == null)
		{
			return;
		}

		// Noted before core gets the event, because core nulls the target on some
		// drops and we null it ourselves on the rest.
		dropped |= client.getMouseCurrentButton() == 0;

		boolean draggingOurs = isOurs(dragged);
		boolean droppingOnOurs = isOurs(target);

		if (!draggingOurs && !droppingOnOurs)
		{
			return;
		}

		client.setDraggedOnWidget(null);

		// Still held down: nothing to do until it is let go.
		if (client.getMouseCurrentButton() != 0)
		{
			return;
		}

		try
		{
			drop(dragged, target, draggingOurs, droppingOnOurs);
		}
		catch (Exception e)
		{
			log.warn("Folder drop failed", e);
		}
	}

	/**
	 * Draw the column again once core has finished with a drop.
	 *
	 * Core rebuilds its tabs on release for every drop it does not otherwise
	 * handle, moving a bank item included, and that rebuild takes our rows with
	 * it. Doing this on the next tick instead left a frame of core's flat column
	 * on screen, which is what the flicker was: core does its own rebuild inside
	 * the same handler, so it never shows one.
	 */
	private void repairAfterDrop()
	{
		if (dropped)
		{
			dropped = false;
			redraw();
		}
	}

	/**
	 * The other half of {@link #onWidgetDrag}, running after core instead of
	 * before it.
	 *
	 * A separate object because the event bus requires a subscriber to be named
	 * after its event, so one class cannot subscribe to {@code WidgetDrag} twice,
	 * and the half above has to stay ahead of core to take a drop off it.
	 */
	static class DropRepair
	{
		private final Runnable repair;

		DropRepair(Runnable repair)
		{
			this.repair = repair;
		}

		@Subscribe(priority = -100)
		public void onWidgetDrag(WidgetDrag event)
		{
			repair.run();
		}
	}

	/** A folder row and a folder tile are the same folder, so both views answer. */
	private boolean isOurs(Widget widget)
	{
		return strip.isOurs(widget) || overview.isOurs(widget);
	}

	@Nullable
	private String folderIdAt(Widget widget)
	{
		String id = strip.folderIdAt(widget);
		return id != null ? id : overview.folderIdAt(widget);
	}

	/**
	 * The tab a widget belongs to, read off the widget rather than looked up in
	 * anything remembered while drawing. What we remember goes stale as soon as
	 * core rebuilds its tabs, and is never written at all for a view with no
	 * folders in it, either of which would leave a tab that plainly exists not
	 * answering to its own name.
	 */
	@Nullable
	private String tagAt(@Nullable Widget widget)
	{
		if (widget == null || isOurs(widget))
		{
			return null;
		}

		// Dynamic children report their container's id, which keeps the folder
		// options off every other named widget in the interface.
		int container = widget.getId();
		if (container != InterfaceID.Bankmain.ITEMS_CONTAINER && container != InterfaceID.Bankmain.ITEMS)
		{
			return null;
		}

		String name = widget.getName();
		if (name == null || name.isEmpty())
		{
			return null;
		}

		String tag = Text.removeTags(name);
		return tabOrder.isTab(tag) ? tag : null;
	}

	private void drop(Widget dragged, Widget target, boolean draggingOurs, boolean droppingOnOurs)
	{
		String targetFolder = folderIdAt(target);
		String draggedFolder = folderIdAt(dragged);

		if (droppingOnOurs && targetFolder != null)
		{
			if (draggingOurs)
			{
				if (draggedFolder != null)
				{
					actions.moveFolderToFolder(draggedFolder, targetFolder);
				}
				return;
			}

			String tag = tagAt(dragged);
			if (tag != null)
			{
				Folder folder = store.byId(targetFolder);
				if (folder != null)
				{
					actions.fileInto(folder, tag);
				}
			}
			// A bank item dropped on a folder row does nothing; a folder is
			// not a tag and has nothing to tag the item with.
			return;
		}

		if (draggingOurs && draggedFolder != null)
		{
			String tag = tagAt(target);
			if (tag != null)
			{
				actions.moveFolderToTag(draggedFolder, tag);
			}
		}
	}
}

package com.foldersforbanktags;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;

/**
 * One collapsible group of tag tabs.
 *
 * A folder holds nothing but names. Which tags exist, what they are called,
 * what icon they use and what items carry them all stay with Bank Tags, so
 * deleting a folder can't lose anything.
 *
 * Serialised straight to JSON by {@link FolderStore}, so these field names are
 * the stored format, and Gson needs the no-args constructor Lombok leaves in
 * place.
 */
@Data
public class Folder
{
	/** Stable across renames, so membership survives one. */
	private String id;

	private String name;

	/**
	 * Item id drawn on the folder row, or 0 to borrow the icon of the first tab
	 * inside it. Borrowing is the default so that a folder of three herblore tabs
	 * looks like herblore without anyone picking an icon.
	 */
	private int icon;

	private boolean collapsed;

	/**
	 * Member tags, standardised. Not an order: the rows are ordered by the Bank
	 * Tags tab list, so dragging a tab about in the ordinary way still works.
	 */
	private List<String> tags = new ArrayList<>();
}

package com.foldersforbanktags;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetConfig;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

/**
 * Folders in the tag tab overview, the grid of every tab reached from the tag
 * tab button at the top left of the bank.
 *
 * Same idea as the side column: core draws its grid of tab icons into the
 * bank's item container, then this hides the tabs inside closed folders, drops
 * in a folder tile where each one belongs and repacks the grid. Opening a
 * folder here and in the column are the same action on the same folder, so the
 * two views can't disagree.
 *
 * Two differences from the column matter. Core reuses its tiles from a fixed
 * starting index rather than rebuilding them, so it takes one of ours once
 * there are enough tabs, which is noticed and recovered from rather than
 * prevented. And the overview has no real items in it, so the bank's scroll
 * height is whatever the grid says it is, and the height core just wrote has to
 * be corrected.
 */
@Slf4j
@Singleton
class OverviewGrid
{
	/**
	 * The pseudo tag core opens for this view. The same string as the key the tab
	 * list is stored under, which is why one constant covers both.
	 */
	private static final String TAG_TABS = BankTagsPlugin.TAG_TABS_CONFIG;

	private static final int ITEM_WIDTH = BankTagsPlugin.BANK_ITEM_WIDTH;
	private static final int ITEM_HEIGHT = BankTagsPlugin.BANK_ITEM_HEIGHT;
	private static final int X_PADDING = BankTagsPlugin.BANK_ITEM_X_PADDING;
	private static final int Y_PADDING = BankTagsPlugin.BANK_ITEM_Y_PADDING;
	private static final int PER_ROW = BankTagsPlugin.BANK_ITEMS_PER_ROW;
	private static final int START_X = BankTagsPlugin.BANK_ITEM_START_X;
	private static final int START_Y = BankTagsPlugin.BANK_ITEM_START_Y;

	/** The underline drawn beneath a folder and the tabs inside it. */
	private static final int BAR_HEIGHT = 2;
	private static final int BAR_GAP = 1;

	private final Client client;
	private final FolderStore store;
	private final FoldersForBankTagsConfig config;
	private final BankTagsService bankTags;
	private final Provider<FolderActions> actions;

	private final List<Widget> created = new ArrayList<>();
	private final Set<Widget> ours = Collections.newSetFromMap(new IdentityHashMap<>());
	private final List<Widget> tiles = new ArrayList<>();
	private final List<Widget> marks = new ArrayList<>();
	private final List<Widget> bars = new ArrayList<>();
	private int tilesUsed;
	private int marksUsed;
	private int barsUsed;

	private final Map<Widget, String> folderByWidget = new IdentityHashMap<>();
	private final Map<Widget, String> tagByWidget = new IdentityHashMap<>();

	/** A tab tile we hid, and a folder tile we showed. Both should have stayed that way. */
	private Widget hiddenWitness;
	private Widget shownWitness;

	@Inject
	OverviewGrid(
		Client client,
		FolderStore store,
		FoldersForBankTagsConfig config,
		BankTagsService bankTags,
		Provider<FolderActions> actions)
	{
		this.client = client;
		this.store = store;
		this.config = config;
		this.bankTags = bankTags;
		this.actions = actions;
	}

	boolean isActive()
	{
		return TAG_TABS.equals(bankTags.getActiveTag());
	}

	/**
	 * Rearrange the grid.
	 *
	 * @param order the tab order the side column drew, so both views agree
	 * @return the height the bank should scroll to, or -1 to leave core's alone
	 */
	int refresh(List<String> order)
	{
		if (!isActive() || store.isEmpty() || order.isEmpty())
		{
			return -1;
		}

		Widget parent = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (parent == null)
		{
			return -1;
		}

		Widget[] children = parent.getChildren();
		if (children == null)
		{
			return -1;
		}

		// Core reuses tiles from a fixed index and only walks as many as it has
		// tabs, so enough tabs and it walks into ours and turns one into a tab
		// icon. It has just hidden everything it isn't using, so any of ours still
		// showing is one it has taken.
		for (Widget child : children)
		{
			if (child != null && !child.isHidden() && ours.contains(child))
			{
				forget();
				break;
			}
		}

		Map<String, Widget> byTag = scan(children, order);
		if (byTag.isEmpty())
		{
			return -1;
		}

		return draw(parent, byTag, Rows.build(store, order));
	}

	/**
	 * Core's tiles, by tab. Core hides every item in the bank before drawing this
	 * view and shows only the tiles it is using, so anything still showing with a
	 * tab's name on it is one of them. That tells them apart from the real bank
	 * items without having to know where core's tiles start.
	 */
	private Map<String, Widget> scan(Widget[] children, List<String> order)
	{
		Set<String> known = new HashSet<>(order);
		Map<String, Widget> byTag = new HashMap<>();

		for (Widget child : children)
		{
			if (child == null || child.isHidden() || ours.contains(child))
			{
				continue;
			}

			String name = child.getName();
			if (name == null || name.isEmpty())
			{
				continue;
			}

			String tag = Text.removeTags(name);
			if (known.contains(tag))
			{
				byTag.putIfAbsent(tag, child);
			}
		}

		return byTag;
	}

	/** Where a tile ended up, and which folder it speaks for. */
	static final class Placed
	{
		private final Object folder;
		private final int x;
		private final int y;

		Placed(@Nullable Object folder, int x, int y)
		{
			this.folder = folder;
			this.x = x;
			this.y = y;
		}
	}

	/**
	 * The stretches of tiles that belong to one folder and sit on one row. A run
	 * ends at a different folder, at a tab in no folder, or at the edge of the
	 * row, so a folder that wraps is two runs rather than one line drawn across
	 * the gap.
	 *
	 * A run of one tile still gets a line when the folder has tiles on another row,
	 * because then the line is the only thing saying the stray tile belongs to the
	 * folder above it. The tile a wrap leaves on its own is the common case. What
	 * is left out is a folder whose whole presence in the grid is one tile, which
	 * is a closed folder: there is nothing under it to group, and a line would
	 * claim the tab beside it.
	 *
	 * @return {first, last} index pairs into {@code placed}
	 */
	static List<int[]> runs(List<Placed> placed)
	{
		Map<Object, Integer> tiles = new IdentityHashMap<>();
		for (Placed tile : placed)
		{
			if (tile.folder != null)
			{
				tiles.merge(tile.folder, 1, Integer::sum);
			}
		}

		List<int[]> out = new ArrayList<>();

		int i = 0;
		while (i < placed.size())
		{
			Placed first = placed.get(i);
			if (first.folder == null)
			{
				i++;
				continue;
			}

			int end = i;
			while (end + 1 < placed.size()
				&& placed.get(end + 1).folder == first.folder
				&& placed.get(end + 1).y == first.y)
			{
				end++;
			}

			if (end > i || tiles.get(first.folder) > 1)
			{
				out.add(new int[]{i, end});
			}

			i = end + 1;
		}

		return out;
	}

	private int draw(Widget parent, Map<String, Widget> byTag, List<Rows.Row> rows)
	{
		tilesUsed = 0;
		marksUsed = 0;
		barsUsed = 0;
		folderByWidget.clear();
		tagByWidget.clear();
		hiddenWitness = null;
		shownWitness = null;

		for (Widget widget : byTag.values())
		{
			widget.setHidden(true);
		}

		for (Widget widget : created)
		{
			widget.setHidden(true);
		}

		List<Placed> placed = new ArrayList<>(rows.size());
		int itemX = START_X;
		int itemY = START_Y;
		int column = 0;

		for (Rows.Row row : rows)
		{
			Widget widget;

			if (row.isHeader())
			{
				widget = folderTile(parent, row.folder(), byTag, itemX, itemY);
				if (shownWitness == null)
				{
					shownWitness = widget;
				}
			}
			else
			{
				widget = byTag.get(row.tag());
				if (widget == null)
				{
					continue;
				}
				tagByWidget.put(widget, row.tag());
			}

			widget.setOriginalX(itemX);
			widget.setOriginalY(itemY);
			widget.setHidden(false);
			widget.revalidate();

			placed.add(new Placed(row.folder(), itemX, itemY));

			if (++column == PER_ROW)
			{
				column = 0;
				itemX = START_X;
				itemY += Y_PADDING + ITEM_HEIGHT;
			}
			else
			{
				itemX += X_PADDING + ITEM_WIDTH;
			}
		}

		int bottom = itemY + ITEM_HEIGHT;

		if (config.markMembers() && underline(parent, placed))
		{
			bottom += BAR_GAP + BAR_HEIGHT;
		}

		for (Widget widget : byTag.values())
		{
			if (widget.isHidden())
			{
				hiddenWitness = widget;
				break;
			}
		}

		// Core wrote a height for its own grid a moment ago, but ours has different
		// rows in it plus an underline core knows nothing about, so without the
		// corrected one the bank scrolls past the end or stops short of it.
		return bottom;
	}

	/**
	 * Draw a line under each folder and the tabs inside it. In the column a
	 * folder's tabs are the rows beneath it, but in a grid a tab next to a folder
	 * tile looks exactly like a tab next to nothing. The line runs under the
	 * folder and its tabs together, stopping at the end of a row and starting
	 * again on the next when a folder wraps.
	 *
	 * @return whether anything was drawn
	 */
	private boolean underline(Widget parent, List<Placed> placed)
	{
		java.awt.Color colour = config.markerColour();
		boolean drew = false;

		for (int[] run : runs(placed))
		{
			Placed first = placed.get(run[0]);
			Placed last = placed.get(run[1]);

			Widget bar = obtain(bars, barsUsed++, parent, WidgetType.RECTANGLE);
			bar.setFilled(true);
			bar.setTextColor(colour.getRGB() & 0xFFFFFF);
			bar.setOpacity(255 - colour.getAlpha());
			bar.setOriginalX(first.x);
			bar.setOriginalY(first.y + ITEM_HEIGHT + BAR_GAP);
			bar.setOriginalWidth(last.x - first.x + ITEM_WIDTH);
			bar.setOriginalHeight(BAR_HEIGHT);
			bar.setHidden(false);
			bar.revalidate();
			drew = true;
		}

		return drew;
	}

	private Widget folderTile(Widget parent, Folder folder, Map<String, Widget> byTag, int x, int y)
	{
		String name = ColorUtil.wrapWithColorTag(folder.getName(), JagexColors.MENU_TARGET);
		String id = folder.getId();

		Widget tile = obtain(tiles, tilesUsed++, parent, WidgetType.GRAPHIC);
		tile.setOriginalWidth(ITEM_WIDTH);
		tile.setOriginalHeight(ITEM_HEIGHT);
		tile.setName(name);
		tile.setItemId(icon(folder, byTag));
		tile.setItemQuantity(-1);
		tile.setBorderType(1);

		// As in the column, options on one widget only so each is listed once. The
		// marker drawn over the top has none and clicks through.
		tile.setAction(TabStrip.OP_TOGGLE, folder.isCollapsed() ? "Open" : "Close");
		tile.setAction(TabStrip.OP_RENAME, "Rename folder");
		tile.setAction(TabStrip.OP_ICON, "Change icon");
		tile.setAction(TabStrip.OP_DELETE, "Delete folder");
		tile.setHasListener(true);
		tile.setOnOpListener((JavaScriptCallback) event -> actions.get().onFolderOp(event.getOp() - 1, id));
		tile.setClickMask(tile.getClickMask() | WidgetConfig.DRAG | WidgetConfig.DRAG_ON);
		tile.setDragDeadTime(5);
		tile.setDragDeadZone(5);

		folderByWidget.put(tile, id);

		if (config.showIndicator())
		{
			Widget mark = obtain(marks, marksUsed++, parent, WidgetType.TEXT);
			mark.setText(folder.isCollapsed() ? "+" : "-");
			mark.setFontId(FontID.PLAIN_11);
			mark.setTextColor(0xFFFFFF);
			mark.setTextShadowed(true);
			mark.setXTextAlignment(WidgetTextAlignment.RIGHT);
			mark.setYTextAlignment(WidgetTextAlignment.TOP);
			mark.setOriginalX(x);
			mark.setOriginalY(y);
			mark.setOriginalWidth(ITEM_WIDTH);
			mark.setOriginalHeight(11);
			mark.setHidden(false);
			mark.revalidate();
			folderByWidget.put(mark, id);
		}

		return tile;
	}

	/** A folder with no icon of its own borrows the icon of its first tab. */
	private int icon(Folder folder, Map<String, Widget> byTag)
	{
		if (folder.getIcon() > 0)
		{
			return folder.getIcon();
		}

		for (String tag : folder.getTags())
		{
			Widget widget = byTag.get(tag);
			if (widget != null && widget.getItemId() > 0)
			{
				return widget.getItemId();
			}
		}

		return -1;
	}

	private Widget obtain(List<Widget> pool, int index, Widget parent, int type)
	{
		if (index < pool.size())
		{
			return pool.get(index);
		}

		Widget widget = parent.createChild(-1, type);
		pool.add(widget);
		created.add(widget);
		ours.add(widget);
		return widget;
	}

	private void forget()
	{
		created.clear();
		ours.clear();
		tiles.clear();
		marks.clear();
		bars.clear();
		folderByWidget.clear();
		tagByWidget.clear();
		hiddenWitness = null;
		shownWitness = null;
	}

	/**
	 * Whether core has redrawn the grid from under us: a tab we hid showing again,
	 * or a folder tile we showed now hidden. Either means core rebuilt, which it
	 * does from inside its own option handlers without raising anything we could
	 * listen for.
	 */
	boolean isStale()
	{
		if (!isActive())
		{
			return false;
		}

		return (hiddenWitness != null && !hiddenWitness.isHidden())
			|| (shownWitness != null && shownWitness.isHidden());
	}

	void onBankClosed()
	{
		forget();
	}

	boolean isOurs(@Nullable Widget widget)
	{
		return widget != null && ours.contains(widget);
	}

	@Nullable
	String folderIdAt(@Nullable Widget widget)
	{
		return widget == null ? null : folderByWidget.get(widget);
	}

	@Nullable
	String tagAt(@Nullable Widget widget)
	{
		return widget == null ? null : tagByWidget.get(widget);
	}
}

package com.foldersforbanktags;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.annotation.Nullable;

/**
 * Turns the tab list and the folder list into rows to draw.
 *
 * Shared by the side column and the tag tab overview so the two can't drift: a
 * folder sits in the same place, holds the same tabs and is open or closed in
 * both, since both read the same answer.
 */
final class Rows
{
	private Rows()
	{
	}

	static final class Row
	{
		/** The tab on this row, or null when the row is a folder heading. */
		private final String tag;

		/** The folder this row is, or the one the tab on it belongs to. */
		private final Folder folder;

		private Row(@Nullable String tag, @Nullable Folder folder)
		{
			this.tag = tag;
			this.folder = folder;
		}

		boolean isHeader()
		{
			return tag == null;
		}

		@Nullable
		String tag()
		{
			return tag;
		}

		@Nullable
		Folder folder()
		{
			return folder;
		}
	}

	/**
	 * The tab list reordered so each folder's tabs sit together, at the position
	 * of whichever of them comes first. This is both what gets drawn and what gets
	 * written back to Bank Tags, so turn the plugin off and the tabs that were in
	 * a folder are still side by side, just without the heading.
	 */
	static List<String> grouped(FolderStore store, List<String> tags)
	{
		List<String> out = new ArrayList<>(tags.size());
		Set<String> done = new HashSet<>();

		for (String tag : tags)
		{
			Folder folder = store.folderOf(tag);
			if (folder == null)
			{
				out.add(tag);
				continue;
			}

			if (!done.add(folder.getId()))
			{
				continue;
			}

			for (String member : tags)
			{
				if (store.folderOf(member) == folder)
				{
					out.add(member);
				}
			}
		}

		return out;
	}

	/**
	 * What to draw, in order: a heading for each folder, the tabs inside the open
	 * ones, and everything not in a folder where it already was.
	 *
	 * @param tags the tab list, already {@link #grouped}
	 */
	static List<Row> build(FolderStore store, List<String> tags)
	{
		List<Row> out = new ArrayList<>();
		Set<String> done = new HashSet<>();

		for (String tag : tags)
		{
			Folder folder = store.folderOf(tag);
			if (folder == null)
			{
				out.add(new Row(tag, null));
				continue;
			}

			if (!done.add(folder.getId()))
			{
				continue;
			}

			out.add(new Row(null, folder));

			if (!folder.isCollapsed())
			{
				for (String member : tags)
				{
					if (store.folderOf(member) == folder)
					{
						out.add(new Row(member, folder));
					}
				}
			}
		}

		return out;
	}

	/** Every tab, in order, with no folders applied. */
	static List<Row> flat(List<String> tags)
	{
		List<Row> out = new ArrayList<>(tags.size());
		for (String tag : tags)
		{
			out.add(new Row(tag, null));
		}
		return out;
	}
}

package com.foldersforbanktags;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.util.Text;

/**
 * Moves tabs around in the Bank Tags plugin's own ordered list.
 *
 * The tab order stays Bank Tags' property; this plugin keeps no copy of it and
 * doesn't decide it. A folder draws at the position of its first member, so
 * dragging tabs about in the ordinary way still works. We only reorder to keep
 * a folder's members next to each other after one has been filed into it, and
 * to move a whole folder when its header is dragged.
 *
 * Writes go through {@link TabManager} rather than straight to config, so the
 * list core holds in memory and the one on disk can't drift apart, and a later
 * {@code save()} by core writes back what is already stored.
 */
@Slf4j
@Singleton
class TabOrder
{
	private final TabManager tabManager;

	/**
	 * Set while we are writing the tab list. Bank Tags' save posts its config
	 * event on the calling thread, so this is still set when our own handler sees
	 * it, which is what stops our write looking like someone else's edit.
	 */
	private boolean writing;

	@Inject
	TabOrder(TabManager tabManager)
	{
		this.tabManager = tabManager;
	}

	/**
	 * Whether a name is one of the tag tabs. Asked of core rather than of anything
	 * we remember, since a tab made a moment ago is a tab whether or not the
	 * column has been redrawn since.
	 */
	boolean isTab(String tag)
	{
		String key = Text.standardize(tag);
		if (key.isEmpty())
		{
			return false;
		}

		for (TagTab tab : tabManager.getTabs())
		{
			if (tab.getTag().equals(key))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Move {@code moving} so it sits immediately before or after {@code anchor}.
	 *
	 * @param expected the tab names the drawn column was built from; the write is
	 *                 refused unless core's list still matches, so a list emptied
	 *                 or replaced underneath us can't be saved over the real one
	 * @return whether the order changed
	 */
	boolean move(List<String> moving, String anchor, boolean after, List<String> expected)
	{
		if (moving.isEmpty())
		{
			return false;
		}

		List<TagTab> tabs = tabManager.getTabs();
		if (!matches(tabs, expected))
		{
			log.debug("Refusing to reorder: core's tab list is not the one we drew");
			return false;
		}

		List<TagTab> picked = new ArrayList<>(moving.size());
		for (String tag : moving)
		{
			TagTab tab = find(tabs, tag);
			if (tab != null)
			{
				picked.add(tab);
			}
		}

		TagTab target = find(tabs, anchor);
		if (picked.isEmpty() || target == null || picked.contains(target))
		{
			return false;
		}

		List<String> before = names(tabs);

		tabs.removeAll(picked);
		int at = tabs.indexOf(target) + (after ? 1 : 0);
		tabs.addAll(at, picked);

		if (names(tabs).equals(before))
		{
			return false;
		}

		write();
		return true;
	}

	/**
	 * Rewrite the tab list into the order the plugin is drawing, so the grouping
	 * lives in Bank Tags' own list and turning this plugin off leaves a folder's
	 * tabs still sitting together. Nothing is added or removed, only moved, and
	 * the write is refused unless {@code desired} is the same set of tabs core is
	 * holding.
	 *
	 * @return whether the order changed
	 */
	boolean normalize(List<String> desired, List<String> expected)
	{
		List<TagTab> tabs = tabManager.getTabs();
		if (!matches(tabs, expected))
		{
			log.debug("Refusing to reorder: core's tab list is not the one we drew");
			return false;
		}

		List<String> current = names(tabs);
		if (current.equals(desired))
		{
			return false;
		}

		// Only reordering is allowed here, so check it really is a permutation
		// first. A name repeated, or one missing, would drop a tab on the floor.
		if (new HashSet<>(desired).size() != desired.size()
			|| !new HashSet<>(desired).equals(new HashSet<>(current)))
		{
			log.warn("Refusing to reorder: {} is not a permutation of the tab list", desired);
			return false;
		}

		Map<String, TagTab> byTag = new HashMap<>();
		for (TagTab tab : tabs)
		{
			byTag.put(tab.getTag(), tab);
		}

		List<TagTab> reordered = new ArrayList<>(desired.size());
		for (String tag : desired)
		{
			reordered.add(byTag.get(tag));
		}

		tabs.clear();
		tabs.addAll(reordered);
		write();
		return true;
	}

	/** Whether the tab list is being written by us right now. */
	boolean isWriting()
	{
		return writing;
	}

	private void write()
	{
		writing = true;
		try
		{
			tabManager.save();
		}
		finally
		{
			writing = false;
		}
	}

	/**
	 * Whether core's in-memory list is the one the column was drawn from. Compares
	 * membership and not order: the point is to catch a list that has been cleared
	 * (which happens whenever core's own strip is not running) before
	 * {@code save()} writes that emptiness to config and takes every tab with it.
	 */
	private boolean matches(List<TagTab> tabs, List<String> expected)
	{
		if (tabs.size() != expected.size() || tabs.isEmpty())
		{
			return false;
		}
		return names(tabs).containsAll(expected);
	}

	private static List<String> names(List<TagTab> tabs)
	{
		List<String> out = new ArrayList<>(tabs.size());
		for (TagTab tab : tabs)
		{
			out.add(tab.getTag());
		}
		return out;
	}

	@Nullable
	private static TagTab find(List<TagTab> tabs, String tag)
	{
		String key = Text.standardize(tag);
		for (TagTab tab : tabs)
		{
			if (tab.getTag().equals(key))
			{
				return tab;
			}
		}
		return null;
	}
}

